u0915\u093f\u0915\u0924\u093e (SEM formulation), \u092a\u0942\u0930\u094d\u0923 \u0921\u0947\u091f\u093e \u091c\u0928\u0930\u0947\u0936\u0928 \u092a\u0948\u0930\u093e\u092e\u0940\u091f\u0930\u094d\u0938 (p, N, gamma, noise), \u0915\u0902\u091f\u094d\u0930\u094b\u0932\u094d\u0938 (Standard CAM, Latent LiNGAM, FCI), \u092e\u093e\u0924\u094d\u0930\u093e\u0924\u094d\u092e\u0915 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 (F1, SHD, CSER), \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e \u092a\u0930\u0940\u0915\u094d\u0937\u0923, \u0914\u0930 \u0938\u094d\u091f\u094d\u0930\u0947\u0938-\u091f\u0947\u0938\u094d\u091f\u093f\u0902\u0917 \u0915\u094b \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0936\u093e\u092e\u093f\u0932 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964", "stage": "result", "answer": "# \u0905\u0928\u0911\u092c\u094d\u091c\u0930\u094d\u0935\u094d\u0921 \u0915\u0949\u092e\u0928 \u0915\u0949\u091c\u093c\u0947\u0938 \u0915\u0947 \u0924\u0939\u0924 CAMUV \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e \u0906\u0927\u093e\u0930\u093f\u0924 \u0915\u0949\u091c\u093c\u0932 \u0921\u093f\u0938\u094d\u0915\u0935\u0930\u0940: \u092a\u0942\u0930\u094d\u0923 \u090f\u0915\u094d\u0938\u092a\u0947\u0930\u093f\u092e\u0947\u0902\u091f\u0932 \u0921\u093f\u091c\u093c\u093e\u0907\u0928\n\n---\n\n## 1. \u0938\u092e\u0938\u094d\u092f\u093e \u0915\u0940 \u0930\u0942\u092a\u0930\u0947\u0916\u093e \u0914\u0930 \u0909\u0926\u094d\u0926\u0947\u0936\u094d\u092f (Problem Formulation & Objective)\n\n### 1.1 \u0938\u0902\u0926\u0930\u094d\u092d \u090f\u0935\u0902 \u0936\u094b\u0927 \u092a\u094d\u0930\u0936\u094d\u0928\n\u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u0915\u0949\u091c\u093c\u0932 \u0921\u093f\u0938\u094d\u0915\u0935\u0930\u0940 (Causal Discovery) \u0935\u093f\u0927\u093f\u092f\u093e\u0901 \u092a\u094d\u0930\u093e\u092f\u0903 **\u0915\u0949\u091c\u093c\u0932 \u0938\u092b\u093c\u093f\u0936\u093f\u090f\u0902\u0938\u0940 (Causal Sufficiency)** \u0915\u0940 \u0927\u093e\u0930\u0923\u093e \u092a\u0930 \u0928\u093f\u0930\u094d\u092d\u0930 \u0915\u0930\u0924\u0940 \u0939\u0948\u0902\u2014\u0905\u0930\u094d\u0925\u093e\u0924 \u092f\u0939 \u092e\u093e\u0928\u0924\u0940 \u0939\u0948\u0902 \u0915\u093f \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u092e\u0947\u0902 \u0936\u093e\u092e\u093f\u0932 \u0938\u092d\u0940 \u092a\u094d\u0930\u093e\u0938\u0902\u0917\u093f\u0915 \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u0915\u093e\u0930\u0923 (common causes) \u092a\u094d\u0930\u0947\u0915\u094d\u0937\u093f\u0924 (observed) \u0939\u0948\u0902\u0964 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0921\u0947\u091f\u093e \u092e\u0947\u0902 \u092f\u0939 \u092e\u093e\u0928\u094d\u092f\u0924\u093e \u0905\u0915\u094d\u0938\u0930 \u091f\u0942\u091f \u091c\u093e\u0924\u0940 \u0939\u0948, \u091c\u0939\u093e\u0901 \u0905\u0935\u094d\u092f\u0915\u094d\u0924 \u091a\u0930 (latent/unobserved variables $U$) \u090f\u0915 \u0938\u093e\u0925 \u0915\u0908 \u092a\u094d\u0930\u0947\u0915\u094d\u0937\u093f\u0924 \u091a\u0930\u094b\u0902 \u0915\u094b \u092a\u094d\u0930\u092d\u093e\u0935\u093f\u0924 \u0915\u0930 \u092d\u094d\u0930\u093e\u092e\u0915 (spurious) \u0938\u0939\u0938\u0902\u092c\u0902\u0927 \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964\n\n**\u0936\u094b\u0927 \u092a\u094d\u0930\u0936\u094d\u0928:** *\u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u090f\u0921\u093f\u091f\u093f\u0935 \u0938\u0902\u092c\u0902\u0927\u094b\u0902 \u0914\u0930 \u0905\u0928\u0911\u092c\u094d\u091c\u0930\u094d\u0935\u094d\u0921 \u0915\u0949\u092e\u0928 \u0915\u0949\u091c\u093c\u0947\u0938 (Unobserved Common Causes) \u0935\u093e\u0932\u0947 \u0921\u0947\u091f\u093e \u092e\u0947\u0902 CAMUV (Causal Additive Models with Unobserved Variables) \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 \u0915\u0949\u091c\u093c\u0932 \u0938\u0902\u092c\u0902\u0927\u094b\u0902 \u0914\u0930 \u0917\u0941\u092a\u094d\u0924 \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0930\u094b\u0902 \u0915\u0940 \u0938\u091f\u0940\u0915 \u092a\u0939\u091a\u093e\u0928 \u0915\u0948\u0938\u0947 \u0915\u0940 \u091c\u093e \u0938\u0915\u0924\u0940 \u0939\u0948?*\n\n### 1.2 \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0932\u0915\u094d\u0937\u094d\u092f\n1. \u092f\u0939 \u092e\u093e\u092a\u0928\u093e \u0915\u093f CAMUV \u0915\u093f\u0938 \u0938\u0940\u092e\u093e \u0924\u0915 \u092a\u094d\u0930\u0924\u094d\u092f\u0915\u094d\u0937 \u0915\u0949\u091c\u093c\u0932 \u090f\u091c\u0947\u0938 ($X_i \\to X_j$) \u0915\u094b \u0917\u0941\u092a\u094d\u0924 \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0930\u094d\u0938 ($X_i \\leftrightarrow X_j$) \u0938\u0947 \u0905\u0932\u0917 \u092a\u0939\u091a\u093e\u0928 \u0938\u0915\u0924\u093e \u0939\u0948\u0964\n2. \u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u0921\u0947\u091f\u093e \u0906\u0915\u093e\u0930\u094b\u0902 ($N$), \u0917\u094d\u0930\u093e\u092b \u091c\u091f\u093f\u0932\u0924\u093e\u0913\u0902 ($p$), \u0914\u0930 \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u093f\u0902\u0917 \u0915\u0940 \u0924\u0940\u0935\u094d\u0930\u0924\u093e\u0913\u0902 \u092e\u0947\u0902 CAMUV \u0915\u0940 \u0938\u0902\u0935\u0947\u0926\u0928\u0936\u0940\u0932\u0924\u093e \u0914\u0930 \u0926\u0943\u0922\u093c\u0924\u093e (robustness) \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092c\u0947\u0938\u0932\u093e\u0907\u0928 \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e\u094d\u0938 \u0938\u0947 \u0915\u0930\u0928\u093e\u0964\n\n---\n\n## 2. \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0914\u0930 \u0924\u093e\u0930\u094d\u0915\u093f\u0915 \u0906\u0927\u093e\u0930 (Theoretical & Methodological Rationale)\n\n### 2.1 CAMUV \u0915\u093e \u0915\u093e\u0930\u094d\u092f-\u0938\u093f\u0926\u094d\u0927\u093e\u0902\u0924\nCAMUV \u0938\u094d\u091f\u094d\u0930\u0915\u094d\u091a\u0930\u0932 \u0907\u0915\u094d\u0935\u0947\u0936\u0928 \u092e\u0949\u0921\u0932\u094d\u0938 (SEM) \u0915\u094b \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u090f\u0921\u093f\u091f\u093f\u0935 \u0928\u0949\u0907\u091c\u093c \u092b\u094d\u0930\u0947\u092e\u0935\u0930\u094d\u0915 \u0915\u0947 \u0924\u0939\u0924 \u092e\u0949\u0921\u0932 \u0915\u0930\u0924\u093e \u0939\u0948:\n$$X_i = \\sum_{j \\in Pa(X_i)} f_{ij}(X_j) + \\sum_{k \\in Pa_U(X_i)} g_{ik}(U_k) + \\epsilon_i$$\n\u091c\u0939\u093e\u0901:\n- $Pa(X_i)$ \u092a\u094d\u0930\u0947\u0915\u094d\u0937\u093f\u0924 \u092e\u093e\u0924\u093e-\u092a\u093f\u0924\u093e (observed parents) \u0939\u0948\u0902\u0964\n- $Pa_U(X_i)$ \u0905\u0935\u094d\u092f\u0915\u094d\u0924 \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u0915\u093e\u0930\u0923 (latent confounders) \u0939\u0948\u0902\u0964\n- $\\epsilon_i$ \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u092c\u0939\u093f\u0930\u094d\u091c\u093e\u0924 \u0924\u094d\u0930\u0941\u091f\u093f\u092f\u093e\u0901 (independent exogenous noise terms) \u0939\u0948\u0902\u0964\n- $f_{ij}(\\cdot)$ \u0914\u0930 $g_{ik}(\\cdot)$ \u0938\u0941\u091a\u093e\u0930\u0941 (smooth) \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u092b\u0932\u0928 \u0939\u0948\u0902\u0964\n\n### 2.2 \u092a\u0939\u091a\u093e\u0928 \u092f\u094b\u0917\u094d\u092f\u0924\u093e (Identifiability Mechanism)\n- **\u0915\u0949\u091c\u093c\u0932 \u0938\u092b\u093c\u093f\u0936\u093f\u090f\u0902\u0938\u0940 \u092e\u0947\u0902 (\u0938\u094d\u091f\u0948\u0902\u0921\u0930\u094d\u0921 CAM):** \u092f\u0926\u093f $X \\to Y$, \u0924\u094b \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u0930\u093f\u0917\u094d\u0930\u0947\u0936\u0928 $Y - \\hat{f}(X)$ \u0915\u093e \u0930\u0947\u091c\u093f\u0921\u094d\u092f\u0942\u0905\u0932 $\\hat{\\epsilon}_Y$, $X$ \u0938\u0947 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0930\u0942\u092a \u0938\u0947 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 ($\\hat{\\epsilon}_Y \\perp X$) \u0939\u094b\u0924\u093e \u0939\u0948, \u091c\u092c\u0915\u093f \u0909\u0932\u091f\u0940 \u0926\u093f\u0936\u093e ($X$ \u0915\u094b $Y$ \u092a\u0930 \u0930\u093f\u0917\u094d\u0930\u0947\u0938 \u0915\u0930\u0928\u0947 \u092a\u0930) \u092e\u0947\u0902 \u0930\u0947\u091c\u093f\u0921\u094d\u092f\u0942\u0905\u0932 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u093e\u0964\n- **\u0905\u0935\u094d\u092f\u0915\u094d\u0924 \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0930 \u0915\u0940 \u0909\u092a\u0938\u094d\u0925\u093f\u0924\u093f \u092e\u0947\u0902 ($X \\leftarrow U \\to Y$):** \u092f\u0926\u093f \u0915\u094b\u0908 \u092a\u094d\u0930\u0924\u094d\u092f\u0915\u094d\u0937 \u090f\u091c \u0928\u0939\u0940\u0902 \u0939\u0948 \u092c\u0932\u094d\u0915\u093f \u0915\u0947\u0935\u0932 \u0938\u093e\u091d\u093e \u0905\u0935\u094d\u092f\u0915\u094d\u0924 \u0915\u093e\u0930\u0923 $U$ \u0939\u0948, \u0924\u094b \u0926\u094b\u0928\u094b\u0902 \u0926\u093f\u0936\u093e\u0913\u0902 ($Y$ on $X$ \u0914\u0930 $X$ on $Y$) \u092e\u0947\u0902 \u0930\u0947\u091c\u093f\u0921\u094d\u092f\u0942\u0905\u0932 \u0914\u0930 \u092a\u094d\u0930\u0947\u0921\u093f\u0915\u094d\u091f\u0930 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 **\u0928\u0939\u0940\u0902** \u0939\u094b\u0924\u0947\u0964\n- **CAMUV \u0915\u093e \u0935\u093f\u092d\u0947\u0926\u0940\u0915\u0930\u0923 (Disambiguation):** CAMUV \u090f\u0921\u093f\u091f\u093f\u0935 \u0928\u0949\u0928-\u092a\u0948\u0930\u093e\u092e\u0940\u091f\u094d\u0930\u093f\u0915 \u092e\u0949\u0921\u0932\u093f\u0902\u0917 (\u091c\u0948\u0938\u0947 Generalized Additive Models / Splines) \u0914\u0930 \u0915\u0930\u094d\u0928\u0947\u0932-\u0906\u0927\u093e\u0930\u093f\u0924 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930\u0924\u093e \u092a\u0930\u0940\u0915\u094d\u0937\u0923\u094b\u0902 (\u091c\u0948\u0938\u0947 HSIC) \u0915\u0947 \u0938\u0902\u092f\u094b\u091c\u0928 \u0938\u0947 \u092f\u0939 \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948 \u0915\u093f \u0915\u094d\u092f\u093e \u0905\u0935\u0936\u093f\u0937\u094d\u091f \u0928\u093f\u0930\u094d\u092d\u0930\u0924\u093e \u0915\u093f\u0938\u0940 \u092a\u094d\u0930\u0924\u094d\u092f\u0915\u094d\u0937 \u092a\u094d\u0930\u092d\u093e\u0935 \u0915\u0947 \u0915\u093e\u0930\u0923 \u0939\u0948, \u0915\u093f\u0938\u0940 \u0932\u0947\u091f\u0947\u0902\u091f \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0930 \u0915\u0947 \u0915\u093e\u0930\u0923 \u0939\u0948, \u092f\u093e \u0926\u094b\u0928\u094b\u0902 \u0915\u0947 \u0938\u0902\u092f\u0941\u0915\u094d\u0924 \u092a\u094d\u0930\u092d\u093e\u0935 \u0915\u0947 \u0915\u093e\u0930\u0923\u0964\n\n---\n\n## 3. \u0921\u0947\u091f\u093e \u091c\u0928\u0930\u0947\u0936\u0928 \u092a\u094d\u0930\u094b\u091f\u094b\u0915\u0949\u0932 (Synthetic Data Generation Protocol)\n\n\u090f\u0915 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u093f\u0924 \u0938\u093f\u0902\u0925\u0947\u091f\u093f\u0915 \u0935\u093e\u0924\u093e\u0935\u0930\u0923 \u0924\u0948\u092f\u093e\u0930 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e \u0924\u093e\u0915\u093f \u0917\u094d\u0930\u093e\u0909\u0902\u0921 \u091f\u094d\u0930\u0941\u0925 \u0915\u0949\u091c\u093c\u0932 \u0917\u094d\u0930\u093e\u092b $\\mathcal{G}^*$ (\u091c\u093f\u0938\u092e\u0947\u0902 \u0921\u093e\u092f\u0930\u0947\u0915\u094d\u091f\u0947\u0921 \u090f\u091c\u0947\u0938 $\\to$ \u0914\u0930 \u092c\u093e\u0908-\u0921\u093e\u092f\u0930\u0947\u0915\u094d\u091f\u0947\u0921 \u090f\u091c\u0947\u0938 $\\leftrightarrow$ \u0936\u093e\u092e\u093f\u0932 \u0939\u0948\u0902) \u092a\u0942\u0930\u094d\u0923\u0924\u0903 \u091c\u094d\u091e\u093e\u0924 \u0939\u094b\u0964\n\n### 3.1 \u0917\u094d\u0930\u093e\u092b \u091f\u094b\u092a\u094b\u0932\u0949\u091c\u0940 (Graph Topologies)\n- **\u0917\u094d\u0930\u093e\u092b \u091c\u0928\u0930\u0947\u091f\u0930 \u092a\u094d\u0930\u0915\u093e\u0930:**\n  - Erd\u0151s-R\u00e9nyi (\u0930\u0948\u0902\u0921\u092e \u0921\u0947\u0902\u0938\u093f\u091f\u0940, \u0914\u0938\u0924 \u0921\u093f\u0917\u094d\u0930\u0940 $d \\in \\{1.5, 3.0\\}$)\n  - Barab\u00e1si-Albert (\u0938\u094d\u0915\u0947\u0932-\u092b\u094d\u0930\u0940 / \u0939\u092c \u0938\u0902\u0930\u091a\u0928\u093e)\n- **\u092a\u094d\u0930\u0947\u0915\u094d\u0937\u093f\u0924 \u091a\u0930\u094b\u0902 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e:** $p \\in \\{5, 10, 20\\}$\n- **\u0905\u0935\u094d\u092f\u0915\u094d\u0924 \u091a\u0930\u094b\u0902 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e:** $q \\in \\{1, 2, 4\\}$ (\u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 $U_k$ \u0915\u092e \u0938\u0947 \u0915\u092e \u0926\u094b \u092f\u093e\u0926\u0943\u091a\u094d\u091b\u093f\u0915 \u092a\u094d\u0930\u0947\u0915\u094d\u0937\u093f\u0924 \u0928\u094b\u0921\u094d\u0938 \u0915\u094b \u092a\u094d\u0930\u092d\u093e\u0935\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948)\u0964\n\n### 3.2 \u0915\u093e\u0930\u094d\u092f\u093e\u0924\u094d\u092e\u0915 \u0938\u0902\u092c\u0902\u0927 \u0914\u0930 \u0928\u0949\u0907\u091c\u093c (Functional Forms & Noise)\n- **\u0917\u0948\u0930-\u0930\u0948\u0916\u093f\u0915 \u092b\u0932\u0928 $f_{ij}, g_{ik}$:**\n  - \u0938\u093f\u0917\u092e\u0949\u0907\u0921\u0932: $f(x) = \\tanh(w \\cdot x)$\n  - \u0924\u094d\u0930\u093f\u0915\u094b\u0923\u092e\u093f\u0924\u0940\u092f: $f(x) = \\sin(w \\cdot x)$\n  - \u0924\u0930\u094d\u0915\u0938\u0902\u0917\u0924/\u092c\u0939\u0941\u092a\u0926: $f(x) = \\frac{x}{1 + x^2}$\n  - \u0935\u091c\u0928 $w \\sim \\text{Uniform}([-1.5, -0.5] \\cup [0.5, 1.5])$ (\u0936\u0942\u0928\u094d\u092f \u0938\u0947 \u0926\u0942\u0930 \u0930\u0916\u0928\u0947 \u0939\u0947\u0924\u0941)\u0964\n- **\u0928\u0949\u0907\u091c\u093c \u0935\u093f\u0924\u0930\u0923 ($\\epsilon_i, U_k$):**\n  - \u092e\u093e\u0928\u0915 \u0917\u0949\u0938\u093f\u092f\u0928: $\\mathcal{N}(0, 1)$\n  - \u0932\u093e\u092a\u094d\u0932\u093e\u0938 (\u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0917\u0948\u0930-\u0917\u0949\u0938\u093f\u092f\u0928): $\\text{Laplace}(0, 1/\\sqrt{2})$\n  - \u090f\u0915\u0938\u092e\u093e\u0928 (Uniform): $\\mathcal{U}(-\\sqrt{3}, \\sqrt{3})$\n- **\u0915\u0928\u094d\u092b\u093e\u0909\u0902\u0921\u093f\u0902\u0917 \u0936\u0915\u094d\u0924\u093f \u0905\u0928\u0941\u092a\u093e\u0924 ($\\gamma$):**\n  $$\\gamma = \\frac{\\text{Var}(g(U))}{\\text{Var}(f(X)) + \\text{Var}(\\epsilon)} \\in \\{0.2 \\text{ [\u0928\u093f\u092e\u094d\u0928]}, 0.6 \\text{ [\u092e\u0927\u094d\u092f\u092e]}, 1.2 \\text{ [\u0909\u091a\u094d\u091a]}\\}$$\n\n### 3.3 \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0917\u094d\u0930\u093f\u0921 (Experimental Factorial Grid)\n- **\u0938\u0948\u0902\u092a\u0932 \u0938\u093e\u0907\u091c ($N$):** $200, 500, 1000, 2500$\n- **\u091f\u094d\u0930\u093e\u092f\u0932\u094d\u0938:** \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0938\u0947\u0932 \u0915\u0949\u0928\u094d\u092b\u093c\u093f\u0917\u0930\u0947\u0936\u0928 \u0915\u0947 \u0932\u093f\u090f $M = 50$ \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u092e\u094b\u0902\u091f\u0947-\u0915\u093e\u0930\u094d\u0932\u094b \u0930\u0947\u092a\u094d\u0932\u093f\u0915\u0947\u0936\u0928\u094d\u0938\u0964 \u0915\u0941\u0932 \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u0930\u0928 = $3 (p) \\times 4 (N) \\times 3 (\\gamma) \\times 50 = 1800$ \u0930\u0928\u0964\n\n---\n\n## 4. \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0915\u0902\u091f\u094d\u0930\u094b\u0932\u094d\u0938 \u0914\u0930 \u092c\u0947\u0938\u0932\u093e\u0907\u0928 \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e (Baselines & Controls)\n\n| \u0936\u094d\u0930\u0947\u0923\u0940 | \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e | \u092e\u0941\u0916\u094d\u092f \u092e\u093e\u0928\u094d\u092f\u0924\u093e\u090f\u0901 | \u0907\u0938 \u092a\u094d\u0930\u092f\u094b\u0917 \u092e\u0947\u0902 \u092d\u0942\u092e\u093f\u0915\u093e |\n| :--- | :--- | :--- | :--- |\n| **\u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935\u093f\u0924 \u0935\u093f\u0927\u093f** | **CAMUV** | \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u090f\u0921\u093f\u091f\u093f\u0935, \u0932\u0947\u091f\u0947\u0902\u091f \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0930\u094d\u0938 \u0905\u0928\u0941\u092e\u0924 | \u092e\u0941\u0916\u094d\u092f \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u0932\u0915\u094d\u0937\u094d\u092f |\n| **\u0938\u092b\u093c\u093f\u0936\u093f\u090f\u0902\u0938\u0940 \u092c\u0947\u0938\u0932\u093e\u0907\u0928** | **Standard CAM** | \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u090f\u0921\u093f\u091f\u093f\u0935, **\u0915\u094b\u0908 \u0932\u0947\u091f\u0947\u0902\u091f \u091a\u0930 \u0928\u0939\u0940\u0902** | \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923: \u092f\u0939 \u0926\u0947\u0916\u0928\u093e \u0915\u093f \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0930 \u0915\u094b \u0928\u091c\u093c\u0930\u0905\u0902\u0926\u093e\u091c\u093c \u0915\u0930\u0928\u0947 \u092a\u0930 \u0915\u093f\u0924\u0928\u0947 \u0917\u0932\u0924 \u0921\u093e\u092f\u0930\u0947\u0915\u094d\u091f\u0947\u0921 \u090f\u091c\u0947\u0938 \u092c\u0928\u0924\u0947 \u0939\u0948\u0902 |\n| **\u0932\u0940\u0928\u093f\u092f\u0930 \u0932\u0947\u091f\u0947\u0902\u091f \u092c\u0947\u0938\u0932\u093e\u0907\u0928** | **Latent LiNGAM (RCD)** | **\u0930\u0948\u0916\u093f\u0915 \u0938\u0902\u092c\u0902\u0927**, \u0917\u0948\u0930-\u0917\u0949\u0938\u093f\u092f\u0928 \u0928\u0949\u0907\u091c\u093c, \u0932\u0947\u091f\u0947\u0902\u091f \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0930\u094d\u0938 \u0905\u0928\u0941\u092e\u0924 | \u092f\u0939 \u092e\u093e\u092a\u0928\u093e \u0915\u093f \u091c\u092c \u0921\u0947\u091f\u093e \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u0939\u094b, \u0924\u092c \u0932\u0940\u0928\u093f\u092f\u0930 \u0932\u0947\u091f\u0947\u0902\u091f \u0935\u093f\u0927\u093f\u092f\u093e\u0901 \u0915\u0948\u0938\u0947 \u0935\u093f\u092b\u0932 \u0939\u094b\u0924\u0940 \u0939\u0948\u0902 |\n| **\u0915\u0902\u0938\u094d\u091f\u094d\u0930\u0947\u0902\u091f-\u092c\u0947\u0938\u094d\u0921 \u092c\u0947\u0938\u0932\u093e\u0907\u0928** | **FCI / RFCI** | \u092e\u0928\u092e\u093e\u0928\u093e \u092b\u0932\u0928, \u0932\u0947\u091f\u0947\u0902\u091f \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0930\u094d\u0938 \u0905\u0928\u0941\u092e\u0924 (PAG \u0906\u0909\u091f\u092a\u0941\u091f) | \u0915\u0902\u0921\u0940\u0936\u0928\u0932 \u0907\u0902\u0921\u093f\u092a\u0947\u0902\u0921\u0947\u0902\u0938 \u0906\u0927\u093e\u0930\u093f\u0924 \u092e\u093e\u0928\u0915 \u0932\u0947\u091f\u0947\u0902\u091f-\u0935\u0947\u0930\u093f\u090f\u092c\u0932 \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915 |\n| **\u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u0938\u092b\u093c\u093f\u0936\u093f\u090f\u0902\u0938\u0940** | **Kernel PC (KPC)** | \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930, \u0938\u092b\u093c\u093f\u0936\u093f\u090f\u0902\u0938\u0940 \u092e\u093e\u0928\u094d\u092f | \u0917\u0948\u0930-\u0930\u0948\u0916\u093f\u0915 \u0938\u0940\u0906\u0908 \u091f\u0947\u0938\u094d\u091f \u0915\u0940 \u0924\u0941\u0932\u0928\u093e |\n\n---\n\n## 5. \u092e\u093e\u0924\u094d\u0930\u093e\u0924\u094d\u092e\u0915 \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 (Quantitative Evaluation Metrics)\n\n\u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0905\u0928\u0941\u092e\u093e\u0928\u093f\u0924 \u0917\u094d\u0930\u093e\u092b $\\hat{\\mathcal{G}}$ \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0917\u094d\u0930\u093e\u092b $\\mathcal{G}^*$ \u0938\u0947 \u0928\u093f\u092e\u094d\u0928 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 \u092a\u0930 \u0915\u0940 \u091c\u093e\u090f\u0917\u0940:\n\n1. **\u0921\u093e\u092f\u0930\u0947\u0915\u094d\u091f\u0947\u0921 \u090f\u091c \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 ($X \\to Y$):**\n   - $\\text{Precision}_{\\to} = \\frac{\\text{TP}_{\\to}}{\\text{TP}_{\\to} + \\text{FP}_{\\to}}$\n   - $\\text{Recall}_{\\to} = \\frac{\\text{TP}_{\\to}}{\\text{TP}_{\\to} + \\text{FN}_{\\to}}$\n   - $\\text{F1}_{\\to} = 2 \\cdot \\frac{\\text{Precision}_{\\to} \\cdot \\text{Recall}_{\\to}}{\\text{Precision}_{\\to} + \\text{Recall}_{\\to}}$\n\n2. **\u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0947\u0921 \u090f\u091c \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 ($X \\leftrightarrow Y$):**\n   - $\\text{Precision}_{\\leftrightarrow}$, $\\text{Recall}_{\\leftrightarrow}$, $\\text{F1}_{\\leftrightarrow}$ (\u0905\u0935\u094d\u092f\u0915\u094d\u0924 \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u0915\u093e\u0930\u0923\u094b\u0902 \u0915\u0940 \u0938\u0939\u0940 \u092a\u0939\u091a\u093e\u0928 \u0915\u093e \u0905\u0928\u0941\u092a\u093e\u0924)\u0964\n   - **\u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u093f\u0902\u0917 \u0938\u094d\u092a\u094d\u092f\u0942\u0930\u093f\u092f\u0938 \u090f\u0930\u0930 \u0930\u0947\u091f (CSER):** \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 $X \\leftrightarrow Y$ \u0915\u094b \u0917\u0932\u0924\u0940 \u0938\u0947 \u092a\u094d\u0930\u0924\u094d\u092f\u0915\u094d\u0937 $X \\to Y$ \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0915\u094d\u0932\u093e\u0938\u093f\u092b\u093e\u0908 \u0915\u0930\u0928\u0947 \u0915\u0940 \u0926\u0930\u0964\n\n3. **\u0938\u092e\u0917\u094d\u0930 \u0917\u094d\u0930\u093e\u092b \u0926\u0942\u0930\u0940:**\n   - **\u0938\u094d\u091f\u094d\u0930\u0915\u094d\u091a\u0930\u0932 \u0939\u0948\u092e\u093f\u0902\u0917 \u0921\u093f\u0938\u094d\u091f\u0947\u0902\u0938 (SHD):** \u0938\u0939\u0940 \u0917\u094d\u0930\u093e\u092b \u0924\u0915 \u092a\u0939\u0941\u0901\u091a\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0906\u0935\u0936\u094d\u092f\u0915 \u090f\u091c \u0907\u0928\u094d\u0938\u0930\u094d\u0936\u0928, \u0921\u093f\u0932\u0940\u0936\u0928 \u0914\u0930 \u0930\u093f\u0935\u0930\u094d\u0938\u0932 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e\u0964\n   - **\u0938\u094d\u091f\u094d\u0930\u0915\u094d\u091a\u0930\u0932 \u0907\u0902\u091f\u0930\u0935\u0947\u0902\u0936\u0928 \u0921\u093f\u0938\u094d\u091f\u0947\u0902\u0938 (SID):** \u0915\u0949\u091c\u093c\u0932 \u0907\u0902\u091f\u0930\u0935\u0947\u0902\u0936\u0928 \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928 \u0915\u0940 \u0936\u0941\u0926\u094d\u0927\u0924\u093e \u0915\u093e \u092e\u093e\u092a\u0928\u0964\n\n4. **\u0915\u0902\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0938\u094d\u0915\u0947\u0932\u0947\u092c\u093f\u0932\u093f\u091f\u0940:**\n   - \u0935\u093e\u0932-\u0915\u094d\u0932\u0949\u0915 \u0930\u0928\u091f\u093e\u0907\u092e (\u0938\u0947\u0915\u0902\u0921) \u092c\u0928\u093e\u092e \u0928\u094b\u0921\u094d\u0938 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e $p$ \u0914\u0930 \u0938\u0948\u0902\u092a\u0932 \u0938\u093e\u0907\u091c $N$\u0964\n\n---\n\n## 6. \u0935\u093f\u0938\u094d\u0924\u0943\u0924 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u090f\u0935\u0902 \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e \u092a\u0930\u0940\u0915\u094d\u0937\u0923 \u092f\u094b\u091c\u0928\u093e (Detailed Analysis Plan)\n\n### 6.1 \u092e\u0941\u0916\u094d\u092f \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e\u090f\u0901 (Testable Hypotheses)\n- **\u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e 1 (H1 - Spurious Edge Elimination):** \u0932\u0947\u091f\u0947\u0902\u091f \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0930\u094d\u0938 \u0915\u0940 \u0909\u092a\u0938\u094d\u0925\u093f\u0924\u093f \u092e\u0947\u0902, CAMUV \u0915\u093e $\\text{Precision}_{\\to}$ \u0938\u094d\u091f\u0948\u0902\u0921\u0930\u094d\u0921 CAM \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0930\u0942\u092a \u0938\u0947 \u0915\u093e\u092b\u0940 \u0905\u0927\u093f\u0915 \u0939\u094b\u0917\u093e, \u0915\u094d\u092f\u094b\u0902\u0915\u093f CAM \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0947\u0921 \u091c\u094b\u0921\u093c\u094b\u0902 \u0915\u094b \u0917\u0932\u0924 \u0924\u0930\u0940\u0915\u0947 \u0938\u0947 \u0921\u093e\u092f\u0930\u0947\u0915\u094d\u091f\u0947\u0921 \u090f\u091c \u092e\u093e\u0928 \u0932\u0947\u0924\u093e \u0939\u0948\u0964\n- **\u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e 2 (H2 - Non-linearity Advantage):** \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u0921\u0947\u091f\u093e \u092e\u0947\u0902, CAMUV \u0915\u093e \u0932\u0947\u091f\u0947\u0902\u091f \u0930\u093f\u0915\u0935\u0930\u0940 F1-\u0938\u094d\u0915\u094b\u0930 ($\\text{F1}_{\\leftrightarrow}$) Latent LiNGAM \u0914\u0930 FCI \u0938\u0947 \u0936\u094d\u0930\u0947\u0937\u094d\u0920 \u0939\u094b\u0917\u093e\u0964\n- **\u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e 3 (H3 - Asymptotic Consistency):** \u0938\u0948\u0902\u092a\u0932 \u0938\u093e\u0907\u091c $N$ \u092c\u0922\u093c\u0928\u0947 \u0915\u0947 \u0938\u093e\u0925, CAMUV \u0915\u093e SHD \u090f\u0915\u0926\u093f\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 (monotonically) \u0936\u0942\u0928\u094d\u092f \u0915\u0940 \u0913\u0930 \u0905\u0917\u094d\u0930\u0938\u0930 \u0939\u094b\u0917\u093e\u0964\n\n### 6.2 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0935\u093f\u0927\u093f (Statistical Testing)\n- \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 \u0915\u0947 \u0905\u0902\u0924\u0930 \u0915\u093e \u0906\u0915\u0932\u0928 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0926\u094b-\u0924\u0930\u092b\u093e \u090f\u0928\u094b\u0935\u093e (Two-way ANOVA) \u092f\u093e \u0917\u0948\u0930-\u092a\u0948\u0930\u093e\u092e\u0940\u091f\u094d\u0930\u093f\u0915 **Wilcoxon Signed-Rank Test** \u0915\u093e \u0909\u092a\u092f\u094b\u0917 (\u092a\u094d\u0930\u0924\u093f\u0926\u094d\u0935\u0902\u0926\u094d\u0935\u0940 \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e\u094d\u0938 \u0915\u0947 \u0935\u093f\u0930\u0941\u0926\u094d\u0927)\u0964\n- \u092c\u0939\u0941-\u0924\u0941\u0932\u0928\u093e \u0938\u0941\u0927\u093e\u0930 (Multiple comparisons correction) \u0915\u0947 \u0932\u093f\u090f Benjamini-Hochberg FDR ($\\alpha = 0.05$) \u0932\u093e\u0917\u0942 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n\n### 6.3 \u0938\u094d\u091f\u094d\u0930\u0947\u0938-\u091f\u0947\u0938\u094d\u091f\u093f\u0902\u0917 \u0914\u0930 \u0938\u0902\u0935\u0947\u0926\u0928\u0936\u0940\u0932\u0924\u093e \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 (Stress Testing)\n- **\u0928\u0949\u0928-\u090f\u0921\u093f\u091f\u093f\u0935\u093f\u091f\u0940 \u0915\u093e \u092a\u094d\u0930\u092d\u093e\u0935:** \u0921\u0947\u091f\u093e \u092e\u0947\u0902 \u0917\u0941\u0923\u0928\u092b\u0932 \u0935\u093e\u0932\u0947 \u0907\u0902\u091f\u0930\u0948\u0915\u094d\u0936\u0928 \u091f\u0930\u094d\u092e\u094d\u0938 \u091c\u094b\u0921\u093c\u0928\u093e:\n  $$X_i = f(X_j) + g(U) + \\delta \\cdot (X_j \\cdot U) + \\epsilon_i$$\n  \u091c\u0939\u093e\u0901 $\\delta \\in [0, 1]$\u0964 \u092f\u0939 \u092a\u0930\u0940\u0915\u094d\u0937\u0923 \u0915\u0930\u0947\u0917\u093e \u0915\u093f \u090f\u0921\u093f\u091f\u093f\u0935\u093f\u091f\u0940 \u0915\u0940 \u0927\u093e\u0930\u0923\u093e \u091f\u0942\u091f\u0928\u0947 \u092a\u0930 CAMUV \u0915\u093e \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928 \u0915\u093f\u0924\u0928\u093e \u0917\u093f\u0930\u0924\u093e \u0939\u0948\u0964\n- **\u0928\u0949\u0907\u091c\u093c \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928 \u0938\u0902\u0935\u0947\u0926\u0928\u0936\u0940\u0932\u0924\u093e:** \u0917\u0949\u0938\u093f\u092f\u0928 \u092c\u0928\u093e\u092e \u0932\u093e\u092a\u094d\u0932\u093e\u0938 \u092c\u0928\u093e\u092e \u092f\u0942\u0928\u093f\u092b\u093c\u0949\u0930\u094d\u092e \u0928\u0949\u0907\u091c\u093c \u0915\u0947 \u0924\u0939\u0924 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930\u0924\u093e \u092a\u0930\u0940\u0915\u094d\u0937\u0923 (HSIC) \u0915\u0940 \u0938\u094d\u0925\u093f\u0930\u0924\u093e \u0915\u0940 \u0924\u0941\u0932\u0928\u093e\u0964\n\n---\n\n## 7. \u0915\u094d\u0930\u093f\u092f\u093e\u0928\u094d\u0935\u092f\u0928 \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u094d\u092f\u0924\u093e \u090f\u0935\u0902 \u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e\u0924\u094d\u092e\u0915 \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0909\u092a\u093e\u092f (Feasibility & Protocols)\n\n1. **\u092e\u0949\u0921\u094d\u092f\u0942\u0932\u0930 \u0938\u0949\u092b\u094d\u091f\u0935\u0947\u092f\u0930 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930:**\n   - **\u092e\u0949\u0921\u094d\u092f\u0942\u0932 A (\u091c\u0928\u0930\u0947\u091f\u0930):** NumPy \u0914\u0930 SciPy \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 \u0938\u093f\u0902\u0925\u0947\u091f\u093f\u0915 DAGs \u0914\u0930 \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u0938\u094d\u091f\u094d\u0930\u0915\u094d\u091a\u0930\u0932 \u0938\u092e\u0940\u0915\u0930\u0923 \u092c\u0928\u093e\u0928\u093e\u0964\n   - **\u092e\u0949\u0921\u094d\u092f\u0942\u0932 B (\u0930\u093f\u0917\u094d\u0930\u0947\u0936\u0928 \u0907\u0902\u091c\u0928):** B-\u0938\u094d\u092a\u094d\u0932\u093e\u0907\u0928\u094d\u0938 \u0906\u0927\u093e\u0930\u093f\u0924 Generalized Additive Models (GAM) \u0915\u093e \u0909\u092a\u092f\u094b\u0917\u0964\n   - **\u092e\u0949\u0921\u094d\u092f\u0942\u0932 C (\u0907\u0902\u0921\u093f\u092a\u0947\u0902\u0921\u0947\u0902\u0938 \u091f\u0947\u0938\u094d\u091f\u0930):** \u0917\u0949\u0938\u093f\u092f\u0928 RBF \u0915\u0930\u094d\u0928\u0947\u0932 \u0914\u0930 \u0917\u093e\u092e\u093e \u0938\u0928\u094d\u0928\u093f\u0915\u091f\u0928 (Gamma approximation) \u0915\u0947 \u0938\u093e\u0925 \u0924\u0947\u091c\u093c HSIC \u091f\u0947\u0938\u094d\u091f\u0964\n   - **\u092e\u0949\u0921\u094d\u092f\u0942\u0932 D (\u0907\u0935\u0948\u0932\u094d\u092f\u0942\u090f\u091f\u0930):** \u0928\u0947\u091f\u0935\u0930\u094d\u0915 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 \u0914\u0930 \u0915\u0928\u094d\u092b\u094d\u092f\u0942\u091c\u0928 \u092e\u0948\u091f\u094d\u0930\u093f\u0915\u094d\u0938 \u0915\u0940 \u0917\u0923\u0928\u093e\u0964\n2. **\u0915\u0902\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0926\u0915\u094d\u0937\u0924\u093e \u092a\u094d\u0930\u092c\u0902\u0927\u0928:**\n   - \u092c\u0921\u093c\u0947 $p$ ($p=20$) \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u093f\u0932\u093f\u092e\u093f\u0928\u0930\u0940 \u0928\u0947\u092c\u0930\u0939\u0941\u0921 \u091a\u092f\u0928 (\u091c\u0948\u0938\u0947 Lasso \u092f\u093e \u0938\u094d\u092a\u094d\u0932\u093e\u0907\u0928-\u0906\u0927\u093e\u0930\u093f\u0924 \u092b\u093c\u0940\u091a\u0930 \u0938\u094d\u0915\u094d\u0930\u0940\u0928\u093f\u0902\u0917) \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 HSIC \u0917\u0923\u0928\u093e\u0913\u0902 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e \u0915\u094b \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u093f\u0924 \u0915\u0930\u0928\u093e\u0964\n\n\u092f\u0939 \u090f\u0915\u094d\u0938\u092a\u0947\u0930\u093f\u092e\u0947\u0902\u091f\u0932 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0938\u094d\u092a\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u0938\u094d\u0925\u093e\u092a\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948 \u0915\u093f \u0915\u0948\u0938\u0947 CAMUV \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u090f\u0921\u093f\u091f\u093f\u0935\u093f\u091f\u0940 \u0915\u093e \u0932\u093e\u092d \u0909\u0920\u093e\u0915\u0930 \u0905\u0928\u0911\u092c\u094d\u091c\u0930\u094d\u0935\u094d\u0921 \u0915\u0949\u092e\u0928 \u0915\u0949\u091c\u093c\u0947\u0938 \u0915\u0940 \u0909\u092a\u0938\u094d\u0925\u093f\u0924\u093f \u092e\u0947\u0902 \u092d\u0940 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0915\u0949\u091c\u093c\u0932 \u0938\u0902\u092c\u0902\u0927\u094b\u0902 \u0914\u0930 \u0932\u0947\u091f\u0947\u0902\u091f \u0915\u0928\u094d\u092b\u093c\u093e\u0909\u0902\u0921\u0930\u094b\u0902 \u0915\u094b \u0938\u091f\u0940\u0915 \u0930\u0942\u092a \u0938\u0947 \u0916\u094b\u091c \u0938\u0915\u0924\u093e \u0939\u0948\u0964", "assumptions": ["\u0905\u0902\u0921\u0930\u0932\u093e\u0907\u0902\u0917 \u0921\u0947\u091f\u093e-\u091c\u0928\u0930\u0947\u091f\u093f\u0902\u0917 \u092a\u094d\u0930\u094b\u0938\u0947\u0938 \u0928\u0949\u0928-\u0932\u0940\u0928\u093f\u092f\u0930 \u090f\u0921\u093f\u091f\u093f\u0935 \u0928\u0949\u0907\u091c\u093c \u092e\u0949\u0921\u0932 (ANM) \u0915\u093e \u092a\u093e\u0932\u0928 \u0915\u0930\u0924\u0940 \u0939\u0948\u0964", "\u0938\u093f\u0902\u0925\u0947\u091f\u093f\u0915 \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u092e\u0947\u0902 \u0915\u094b\u0908 \u0921\u093e\u092f\u0930\u0947\u0915\u094d\u091f\u0947\u0921 \u0938\u093e\u0907\u0915\u093f\u0932\u094d\u0938 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902 (Acyclicity)\u0964", "\u0938\u092d\u0940 \u092c\u0939\u093f\u0930\u094d\u091c\u093e\u0924 \u0928\u0949\u0907\u091c\u093c \u091f\u0930\u094d\u092e\u094d\u0938 \u0914\u0930 \u0932\u0947\u091f\u0947\u0902\u091f \u0935\u0947\u0930\u093f\u090f\u092c\u0932\u094d\u0938 \u092a\u0930\u0938\u094d\u092a\u0930 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0930\u0942\u092a \u0938\u0947 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0939\u0948\u0902\u0964", "\u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e \u092a\u0930\u0940\u0915\u094d\u0937\u0923 \u0914\u0930 \u0907\u0935\u0948\u0932\u094d\u092f\u0942\u090f\u0936\u0928 \u0915\u0947 \u0932\u093f\u090f \u092e\u094b\u0902\u091f\u0947-\u0915\u093e\u0930\u094d\u0932\u094b \u0930\u0947\u092a\u094d\u0932\u093f\u0915\u0947\u0936\u0928\u094d\u0938 (M=50) \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0936\u0915\u094d\u0924\u093f (statistical power > 0.8) \u092a\u094d\u0930\u0926\u093e\u0928 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 \u0939\u0948\u0902\u0964"], "summary": "CAMUV \u0906\u0927\u093e\u0930\u093f\u0924 \u0915\u0949\u091c\u093c\u0932 \u0921\u093f\u0938\u094d\u0915\u0935\u0930\u0940 \u0915\u093e \u092a\u0942\u0930\u094d\u0923 \u0914\u0930 \u0935\u093f\u0938\u094d\u0924\u0943\u0924 \u090f\u0915\u094d\u0938\u092a\u0947\u0930\u093f\u092e\u0947\u0902\u091f\u0932 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0924\u0948\u092f\u093e\u0930 \u0915\u093f\u092f\u093e \u0917\u092f\u093e\u0964", "uncertainties": ["\u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0909\u091a\u094d\u091a \u0906\u092f\u093e\u092e\u094b\u0902 (p > 100) \u092e\u0947\u0902 \u090f\u0921\u093f\u091f\u093f\u0935 \u0930\u093f\u0917\u094d\u0930\u0947\u0936\u0928 \u0914\u0930 HSIC \u092a\u0947\u092f\u0930\u0935\u093e\u0907\u091c\u093c \u091f\u0947\u0938\u094d\u091f\u094d\u0938 \u0915\u093e \u0915\u0902\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0930\u0928\u091f\u093e\u0907\u092e \u0938\u094d\u0915\u0947\u0932\u093f\u0902\u0917 \u0938\u0940\u092e\u093f\u0924 \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948\u0964", "\u092f\u0926\u093f \u0932\u0947\u091f\u0947\u0902\u091f \u0915\u0902\u092b\u093c\u093e\u0909\u0902\u0921\u0930 \u0914\u0930 \u092a\u094d\u0930\u0947\u0915\u094d\u0937\u093f\u0924 \u091a\u0930\u094b\u0902 \u0915\u0947 \u092c\u0940\u091a \u0928\u0949\u0928-\u090f\u0921\u093f\u091f\u093f\u0935 \u0907\u0902\u091f\u0930\u0948\u0915\u094d\u0936\u0928 (\u091c\u0948\u0938\u0947 X * U) \u092c\u0939\u0941\u0924 \u092a\u094d\u0930\u092c\u0932 \u0939\u094b, \u0924\u094b \u090f\u0921\u093f\u091f\u093f\u0935\u093f\u091f\u0940-\u0906\u0927\u093e\u0930\u093f\u0924 \u092a\u0939\u091a\u093e\u0928 \u092f\u094b\u0917\u094d\u092f\u0924\u093e \u092e\u0947\u0902 \u0917\u093f\u0930\u093e\u0935\u091f \u0906 \u0938\u0915\u0924\u0940 \u0939\u0948\u0964"]}", "origin": "completion"}, "llm_response_id": "l8DTapuuFNybpucP6_mM4As", "security_risk": "UNKNOWN", "kind": "ActionEvent", "source_event_index": 13}
